// Run on its own: the caller reads the handle and name of each person who shares a company with $of.
query colleagues($of: String) {
    match { $p: Person, $c: Company, $q: Person, $p worksAt $c, $q worksAt $c }
    where $p.handle = $of and $q.handle != $of
    return { $q }
}

// Run on its own: the caller reads the distinct names of the colleagues of $of's colleagues.
query colleagues_of_colleagues($of: String) {
    match {
        from colleagues($of),
        from { match { from colleagues($q.handle) } return { $q as r } },
    }
    return distinct { $r.name }
}

