// Unbounded traversal is disabled in GQ, so "any number of hops" cannot be one query.
// The caller runs this one-hop step in a loop:
//   1. Call it with $frontier = [$from].
//   2. Collect the returned (handle, name) rows into a visited set.
//   3. Call it again with $frontier = the handles not yet visited.
//   4. Stop when a call adds no new handles.
// The distinct names in the visited set are the answer. $from is included only if
// it is reachable again through a cycle.
query knows_step($frontier: [String]) {
    match { $p: Person, $p knows $f }
    where $p.handle in $frontier
    return distinct { $f.handle, $f.name }
}

