// Run first: returns the 2 most relevant docs by BM25 for $q. The caller takes the two slugs for the next query.
query top_docs($q: String) {
    match {
        let $all = { match { $d: Doc } return { $d } },
        from bm25($all, $d.body, $q) as $score,
    }
    return { $d.slug }
    order { $score desc }
    limit 2
}

// Run second: the caller passes the two slugs from the first query as $a and $b (if only one came back, pass it as both). Returns each doc's slug with the name of each person who knows it.
query who_knows($a: String, $b: String) {
    match { $d: Doc, $p: Person, $p knows $d }
    where $d.slug in [$a, $b]
    return { $d.slug, $p.name }
}

