answer.text:
// GQ cannot express "any number of hops": traversal bounds must be finite and `{1,}` is rejected.
// The caller therefore runs a breadth-first search. Start with $from = the given handle, then
// run this query once for each newly discovered handle, passing that handle as $from.
// Collect the returned handles into a seen set and stop when a round finds none that are new.
// The answer is the distinct `name` values across all rows collected.
query knows_step($from: String) {
    match { $p: Person, $p knows $f }
    where $p.handle = $from
    return distinct { $f.handle, $f.name }
}

