query weighted($q: String, $v: Vector(3)) {
  match {
    $d: Doc
    from distance({ match { $a: Doc } return { $a } }, $a.embedding, $v) as $distance,
    from bm25({ match { $b: Doc } return { $b } }, $b.body, $q) as $score,
    $a = $d
    $b = $d
